        {
          "ErrorEquals": [
            "States.ALL"
          ],
          "Next": "ResolverNotificacion",
          "ResultPath": "$.error_registro_estado_pipeline"
        }
      ],
      "Next": "ResolverNotificacion",
      "Parameters": {
        "ExpressionAttributeValues": {
          ":amb": {
            "S": "dev"
          },
          ":crawler_gold_success": {
            "S": "SUCCESS"
          },
          ":estado": {
            "S": "PIPELINE_COMPLETO"
          },
          ":exec": {
